let prove_post_hint (g : Pulse_Typing_Env.env) (ctxt : FStarC_Reflection_Types.term) (r : (Prims.int, Pulse_Typing_Env.env, (FStarC_Reflection_Types.universe * FStarC_Reflection_Types.term), FStarC_Reflection_Types.term, (Pulse_Typing.post_hint_opt_t -> ((Pulse_Syntax_Base.st_term, Pulse_Syntax_Base.comp) Pulse_Prims.prims_dtuple2 -> (FStarC_Tactics_Types.ref_proofstate -> (Pulse_Syntax_Base.st_term, Pulse_Syntax_Base.comp) Pulse_Prims.prims_dtuple2)))) FStar_Pervasives.dtuple5) (post_hint : Pulse_Typing.post_hint_opt_t) (rng : FStarC_Range_Type.range) : (FStarC_Tactics_Types.ref_proofstate -> (Prims.int, Pulse_Typing_Env.env, (FStarC_Reflection_Types.universe * FStarC_Reflection_Types.term), FStarC_Reflection_Types.term, (Pulse_Typing.post_hint_opt_t -> ((Pulse_Syntax_Base.st_term, Pulse_Syntax_Base.comp) Pulse_Prims.prims_dtuple2 -> (FStarC_Tactics_Types.ref_proofstate -> (Pulse_Syntax_Base.st_term, Pulse_Syntax_Base.comp) Pulse_Prims.prims_dtuple2)))) FStar_Pervasives.dtuple5) =
  (fun ps -> (let x = (Pulse_Typing_Env.push_context g "prove_post_hint" rng) in
  (match post_hint with
    | Pulse_Typing.NoHint -> r
    | (Pulse_Typing.TypeHint (tmp)) -> (Pulse_Checker_Base.retype_checker_result g ctxt Pulse_Typing.NoHint post_hint r)
    | (Pulse_Typing.PostHint (post_hint1)) -> (match r with
        | (FStar_Pervasives.Mkdtuple5 (x1, g2, (u_ty, ty), ctxt', k)) -> (if (not (Pulse_Syntax_Base.eq_tm (Pulse_RuntimeUtils.deep_compress_safe ty) (Pulse_RuntimeUtils.deep_compress_safe (post_hint1).Pulse_Typing.ret_ty))) then (let x2 = (elim_exists_and_pure g2 ctxt' ps) in
          (match x2 with
            | (FStar_Pervasives.Mkdtuple3 (g3, ctxt3, k3)) -> (if (Pulse_Syntax_Base.eq_tm ctxt3 Pulse_Reflection_Util.tm_is_unreachable) then (let x3 = (Pulse_Typing_Env.fresh g3) in
              let x4 = (Pulse_Syntax_Base.mk_ppname_no_range "_posth") in
              let x5 = (Pulse_Syntax_Naming.open_term_nv (post_hint1).Pulse_Typing.post (x4, x3)) in
              let x6 = (Pulse_Typing_Env.push_binding g3 x3 x4 (post_hint1).Pulse_Typing.ret_ty) in
              let x7 = (k_unreach g3 (x4, x3) post_hint1 ps) in
              (FStar_Pervasives.Mkdtuple5 (x3, x6, ((post_hint1).Pulse_Typing.u, (post_hint1).Pulse_Typing.ret_ty), x5, (Pulse_Checker_Base.k_elab_trans x g2 x6 ctxt ctxt' x5 k (Pulse_Checker_Base.k_elab_trans g2 g3 x6 ctxt' ctxt3 x5 k3 x7))))) else (let x3 = (Pulse_PP.pulse_PP_pp__term ty ps) in
              let x4 = (Pulse_PP.fquotes x3) in
              let x5 = (Pulse_PP.indent x4) in
              let x6 = (Pulse_PP.pulse_PP_pp__term (post_hint1).Pulse_Typing.ret_ty ps) in
              let x7 = (Pulse_PP.fquotes x6) in
              let x8 = (Pulse_PP.indent x7) in
              let x9 = (PPrint.(^^) (Pulse_PP.text "does not match the expected") x8) in
              let x10 = (PPrint.(^/^) x5 x9) in
              let x11 = (PPrint.(^^) (Pulse_PP.text "The return type") x10) in
              let x12 = (x11 :: []) in
              (Pulse_Typing_Env.fail_doc x (Some (rng)) x12 ps)))
          )) else (let x2 = (Pulse_Syntax_Base.mk_ppname_no_range "_posth") in
          let x3 = (Pulse_Syntax_Naming.open_term_nv (post_hint1).Pulse_Typing.post (x2, x1)) in
          (if (Pulse_Syntax_Base.eq_tm x3 ctxt') then (FStar_Pervasives.Mkdtuple5 (x1, g2, (u_ty, ty), ctxt', k)) else (let x4 = (prove rng g2 ctxt' x3 false ps) in
          (match x4 with
            | (FStar_Pervasives.Mkdtuple3 (g3, remaining_ctxt, k_post)) -> (let x5 = (mk_penv x true ps) in
              let x6 = (inspect_slprop x5 remaining_ctxt ps) in
              let x7 = (FStar_Tactics_Util.filter (fun tmp -> (fun tmp1 -> (match tmp with
