let try_frame_pre (allow_ambiguous : bool) (g : Pulse_Typing_Env.env) (ctxt : FStarC_Reflection_Types.term) (d : (Pulse_Syntax_Base.st_term, Pulse_Syntax_Base.comp) Pulse_Prims.prims_dtuple2) (res_ppname : Pulse_Syntax_Base.ppname0) (ps : FStarC_Tactics_Types.ref_proofstate) : (Prims.int, Pulse_Typing_Env.env, (FStarC_Reflection_Types.universe * FStarC_Reflection_Types.term), FStarC_Reflection_Types.term, (Pulse_Typing.post_hint_opt_t -> ((Pulse_Syntax_Base.st_term, Pulse_Syntax_Base.comp) Pulse_Prims.prims_dtuple2 -> (FStarC_Tactics_Types.ref_proofstate -> (Pulse_Syntax_Base.st_term, Pulse_Syntax_Base.comp) Pulse_Prims.prims_dtuple2)))) FStar_Pervasives.dtuple5 =
  (let x = (prove (((d).Pulse_Prims.u__1 : Pulse_Syntax_Base.st_term)).Pulse_Syntax_Base.range g ctxt (Pulse_Syntax_Base.comp_pre (d).Pulse_Prims.u__2) allow_ambiguous ps) in
  (match x with
    | (FStar_Pervasives.Mkdtuple3 (g', ctxt', k)) -> (let x1 = (k Pulse_Typing.NoHint { Pulse_Prims.u__1 = (d).Pulse_Prims.u__1;
          u__2 = (Pulse_Typing.add_frame (d).Pulse_Prims.u__2 ctxt') } ps) in
      (Pulse_Checker_Base.checker_result_for_st_typing g ctxt Pulse_Typing.NoHint x1 res_ppname ps))
  ))

